-- case 1: [A01] -1 keeps its sign inside the padding: '000000-1'
CREATE PROCEDURE [AgreedTests].[test 01 [A01 -1 keeps its sign inside the padding: 000000-1]
AS
BEGIN
  CREATE TABLE #Expected (
    [result] varchar(8) NULL
  );
