    [result] varchar(8) NULL
  );
  INSERT INTO #Expected ([result]) VALUES
    (N'000000-1');
  INSERT INTO #Actual
  SELECT dbo.ufnLeadingZeros(-1) AS result;
  EXEC tSQLt.AssertEqualsTable @Expected = N'#Expected', @Actual = N'#Actual';
END;
GO
